root=Path(__file__).resolve().parent
for source in sources:
 source.update(active=False, approval_status='pending_human_review', guidance_status='not_approved')
data={'schema_version':1,'status':'candidate_dossier_not_approved','source_retrieval_date':'2026-11-07','translation_status':'en_source_only_pt_BR_review_required','source_snapshot_status':'Links and bibliographic versions only; no source text snapshots or source-content hashes have been retained. Capture allowed source versions and hashes during human admission.','admission_policy':'No automatic promotion. Human must approve each source and any proposed guidance; independently review uncertainty, rights and translations.','sources':sources}
(root/'candidates.json').write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n')
lines=['# Candidate evidence-admission dossiers','', '**Status: not approved.** These are research notes for a human admission decision. No entry is active product guidance; no diagnosis, therapy or universal numeric constraints follow from these notes.','', 'The agent has inspected linked primary study abstracts, primary author papers or official guidance as individually stated; it has not independently replicated studies or evaluated full methodology when only an abstract was available. Rights, local relevance and Brazilian Portuguese translation require human review.','', 'Source links and bibliographic dates/DOIs are recorded, but source text snapshots and source-content hashes are not retained. Capture permitted source versions and hashes at admission before claiming a reproducible evidence corpus.','', '## Admission workflow','', 'For each source, inspect the cited source and passage, confirm version and rights, assess population and context, review any translation, and decide whether a narrowly worded guidance record is appropriate. Keep rejected and modified candidates in an audit trail; activate nothing based solely on this dossier.','']
for s in sources:
 lines += [f"## {s['id']} — {s['title']}",'', '- **Status:** Inactive; source and proposed guidance require human approval.',f"- **Source:** [{s['type']}]({s['url']}); published {s['published']}"+(f"; DOI {s['doi']}" if 'doi' in s else '')+'.',f"- **Population and scope:** {s['population']} {s['scope']}",f"- **Evidence assessment:** {s['strength']}",f"- **Limits:** {s['limits']}",f"- **Rights and language:** {s['rights']} No approved PT-BR translation exists in this dossier."]
 for p in s['passages']:lines.append(f"- **{p['id']} — source location:** {p['locator']} Paraphrase: {p['paraphrase']}")
 lines += [f"- **Candidate product application — inference, not an approved rule:** {s['candidate']}",f"- **Misuse to avoid:** {s['misuse']}",'']
lines += ['## Cross-source design implications to review','', '- Treat the person’s expressed goals, constraints and corrections as the primary source of their preferences. Neither evidence about a population nor a calendar gap establishes an individual preference.','- When relevant and feasible, offer optional review or retrieval opportunities with provenance and flexible timing; the evidence does not specify one mandatory schedule for every person.','- Report the randomized scheduling trial’s mixed outcomes alongside positive learning-strategy evidence. A proposed plan, assigned hours and self-reported activity are distinct observations; none independently proves improved wellbeing.','- Avoid creating clinical recommendations from general health guidance. Any potentially consequential health claim, adapted population guidance or translated wording needs qualified review.','- Ask optional questions or check-ins when useful, and evaluate actual burden in this application. The EMA trial does not establish an optimal cadence for this product.','']
(root/'dossiers.md').write_text('\n'.join(lines))
print('Prepared',len(sources),'unapproved source dossiers with',sum(len(x['passages']) for x in sources),'passage IDs')
